FILE: app/src/orbit-camera.ts
```ts
import { createArcRotateCamera, type ArcRotateCamera } from "@babylonjs/lite/camera/arc-rotate.js";
import { attachControl } from "@babylonjs/lite/camera/arc-rotate-controls.js";
import { enableArcRotateKeyboardControls } from "@babylonjs/lite/camera/arc-rotate-keyboard-controls.js";
import type { SceneContext } from "@babylonjs/lite/scene/scene.js";

export function createOrbitCamera(canvas: HTMLCanvasElement, scene: SceneContext): ArcRotateCamera {
    const camera = createArcRotateCamera(0, Math.PI / 2, 10, { x: 0, y: 0, z: 0 });
    enableArcRotateKeyboardControls();
    attachControl(camera, canvas, scene, { keyboard: true });
    return camera;
}
```

I created `src/orbit-camera.ts` which builds an `ArcRotateCamera` at radius 10 targeting the origin, calls `enableArcRotateKeyboardControls()` (required before `keyboard: true` is honoured, per note 9), and attaches the default pointer + keyboard controls via `attachControl` with the scene passed so that drag/wheel motion is applied each frame. The one thing I wasn't sure of is whether `enableArcRotateKeyboardControls()` is safe to call repeatedly (it likely installs a factory once and is idempotent, but I can't verify without the implementation).
